arguments.command:
cd /tmp/hwpx_work/template_extracted && python3 -c "import zipfile, os; z=zipfile.ZipFile('/root/training_feedback_ready.hwpx', 'w', zipfile.ZIP_DEFLATED); 
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.startswith('.'): continue
        path = os.path.join(root, f)
        arcname = os.path.relpath(path, '.')
        z.write(path, arcname)
z.close()
print('Repackaged successfully')"

